export const uuidRegex =
  /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/;

export const phoneNumberRegex =
  /(?<![^\s:.,()])(?:\+?\d{1,3}[ -.]*)?(?:\(\d{1,4}\)|\d{1,4})[ -.]?\d{1,4}[ -.]?\d{1,4}[ -.]?\d{4,9}(?![^\s.,()])/;

export const zoomUrlRegex =
  /https?:\/\/(?:[\w-]+\.)?zoom\.us\/[js]\/(\d+)\??(?:[-\\+=&;%@.\w_]*)#?(?:[\w]*)/;

export const domain =
  /(?:^|[ \t])((https?:\/\/)(?:localhost(:\d+)|[\w-]+(?:\.[\w-]+)+)(:\d+)?(\/\S*)?)/;

export const googleMeetUrlRegex =
  /meet\.google\.com\/[a-z]{3}-[a-z]{4}-[a-z]{3}/;

export const trailingSlash = /\/$/;

export const leverInterviewLinkRegex =
  /http[/\w:]*\.lever.co\/interviews\/\w+-\w+-\w+-\w+-\w+/;

export const greenhouseScorecardRegex =
  /https:\/\/[^/%?]+\/guides\/(\d+)\/people\/(\d+)(?:\/interview)?\/?\?application_id=(\d+)/;

export const teamsMeetingUrlRegex =
  /teams.microsoft.com\/l\/meetup-join\/[0-9a-zA-Z./?%=%_\-,:@{"}]+/;

export const ashbyFeedbackLinkRegex =
  /https:\/\/app\.ashbyhq\.com\/interview-briefings\/[0-9a-f-]+\/feedback/;

export const emailRegex =
  /(([^<>()[\]\\.,;:\s@"]+(\.[^<>()[\]\\.,;:\s@"]+)*)|(".+"))@((\[[0-9]{1,3}\.[0-9]{1,3}\.[0-9]{1,3}\.[0-9]{1,3}\])|(([a-zA-Z\-0-9]+\.)+[a-zA-Z]{2,}))/;
