/**
 * Handles showing and hiding the BrightHire sidepanel across all SmartRecruiters pages
 */
import { setupDrawer } from "../../utils/drawer";
import {
  addPassiveMessageListener,
  sendMessageWithTabId,
} from "../../utils/message";
import { onDocumentLoaded } from "../../utils/onDocumentLoaded";
import { queryEl } from "../../utils/query";
import { phoneNumberRegex } from "../../utils/regex";
import { checkUrlMatches } from "../../utils/url";
import { smartrecruitersUrlMap } from "../../utils/urlMapping";

const loadSidepanel = async (): Promise<void> => {
  const { href, pathname } = window.location;

  if (checkUrlMatches(href, smartrecruitersUrlMap)) {
    const candidateDetails = isCandidateUrl(pathname)
      ? await getCandidateDetails()
      : undefined;
    const reloaded = await setupDrawer({ urlParams: candidateDetails });
    if (reloaded) {
      sendMessageWithTabId({ action: "drawerLoading" });
    }
  }
};

onDocumentLoaded(loadSidepanel);

addPassiveMessageListener(({ message }) => {
  if (message.action === "tabUrlChanged") {
    loadSidepanel();
  }
});

const isCandidateUrl = (pathname: string): boolean => {
  const path = pathname.split("/").filter(Boolean);
  return (
    path[0] === "app" &&
    path[1] === "people" &&
    ["candidates", "applications"].includes(path[2])
  );
};

type CandidateDetails = {
  phone: string;
  email: string;
};

const getCandidateDetails = async (): Promise<CandidateDetails | undefined> => {
  const headerEl = await queryEl({ selector: "sr-candidate-personal-info" });
  if (!headerEl) return;

  const details: CandidateDetails = { email: "", phone: "" };
  headerEl.querySelectorAll("spl-typography-body").forEach((el) => {
    if (el.textContent?.includes("@")) {
      details.email = el.textContent;
    }
    if (el.textContent?.match(phoneNumberRegex)) {
      details.phone = el.textContent;
    }
  });
  return details;
};
